package com.urlshortner.urls;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.dao.DataAccessException;
import org.springframework.stereotype.Service;

@Service
public class UrlService {
    public static final class UnknownCode extends RuntimeException {}
    public static final class ExpiredCode extends RuntimeException {}
    public static final class AllocationExhausted extends RuntimeException {}

    private final UrlRepository repository;
    private final CodeGenerator codes;
    private final Clock clock;
    private final Duration maximumExpiry;

    public UrlService(UrlRepository repository, CodeGenerator codes, Clock clock,
            @Value("${shortener.max-expiry-days:7}") long maximumDays) {
        if (maximumDays <= 0) throw new IllegalArgumentException("Invalid maximum expiry configuration");
        this.repository = repository;
        this.codes = codes;
        this.clock = clock;
        this.maximumExpiry = Duration.ofDays(Math.min(maximumDays, 7L));
    }

    // No surrounding transaction: a uniqueness failure must not abort later attempts.
    public UrlRepository.StoredUrl create(String url, Instant expiresAt) {
        if (!Destination.valid(url)) throw new IllegalArgumentException("Invalid destination");
        Instant now = clock.instant();
        if (expiresAt != null && (!expiresAt.isAfter(now)
                || expiresAt.isAfter(now.plus(maximumExpiry)))) {
            throw new IllegalArgumentException("Invalid expiry");
        }
        for (int attempt = 0; attempt < 5; attempt++) {
            try {
                return repository.insert(codes.next(), url, expiresAt);
            } catch (DataAccessException exception) {
                if (!UrlRepository.isCodeConflict(exception)) throw exception;
            }
        }
        throw new AllocationExhausted();
    }

    public String redirect(String code) {
        Instant now = clock.instant();
        var destination = repository.recordRedirect(code, now);
        if (destination.isPresent()) return destination.get();
        var stored = repository.find(code).orElseThrow(UnknownCode::new);
        if (stored.expiresAt() != null && !stored.expiresAt().isAfter(now)) throw new ExpiredCode();
        throw new IllegalStateException("Eligible redirect was not updated");
    }

    public UrlRepository.StoredUrl analytics(String code) {
        return repository.find(code).orElseThrow(UnknownCode::new);
    }
}

package com.urlshortner.urls;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ExpiryCapTest {
    @ParameterizedTest
    @ValueSource(longs = {7, 30, 31, 365, Long.MAX_VALUE})
    void configuredLimitCannotExceedSevenDays(long configuredDays) {
        Instant now = Instant.parse("2026-01-01T00:00:00.123456789Z");
        UrlRepository repository = mock(UrlRepository.class);
        CodeGenerator codes = mock(CodeGenerator.class);
        UrlService service = new UrlService(repository, codes,
                Clock.fixed(now, ZoneOffset.UTC), configuredDays);
        String url = "https://example.com";
        Instant maximum = now.plus(Duration.ofDays(7));

        assertThrows(IllegalArgumentException.class, () -> service.create(url, maximum.plusNanos(1)));
        assertThrows(IllegalArgumentException.class,
                () -> service.create(url, now.plus(Duration.ofDays(30))));
        verifyNoInteractions(repository, codes);

        var saved = new UrlRepository.StoredUrl("Ab12Cd34", url, now, 0, null, maximum);
        when(codes.next()).thenReturn(saved.code());
        when(repository.insert(saved.code(), url, maximum)).thenReturn(saved);
        assertSame(saved, service.create(url, maximum));
        verify(repository).insert(saved.code(), url, maximum);
        verify(codes).next();
        verifyNoMoreInteractions(repository, codes);
    }

    @ParameterizedTest
    @ValueSource(longs = {0, -1, Long.MIN_VALUE})
    void rejectsNonpositiveConfiguration(long configuredDays) {
        assertThrows(IllegalArgumentException.class, () -> new UrlService(
                mock(UrlRepository.class), mock(CodeGenerator.class), Clock.systemUTC(), configuredDays));
    }
}

