package com.urlshortner.urls;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.databind.JsonNode;
import jakarta.validation.Valid;
import java.net.URI;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeParseException;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
public class UrlController {
    public record CreateRequest(@ValidDestination JsonNode url, JsonNode expiresAt) {}
    public record Created(String code, String shortUrl, String url, Instant createdAt,
            @JsonInclude(JsonInclude.Include.ALWAYS) Instant expiresAt) {}
    public record Analytics(String code, String url, Instant createdAt, long clickCount,
            Instant lastAccessedAt, @JsonInclude(JsonInclude.Include.ALWAYS) Instant expiresAt) {}

    private final UrlService service;
    private final String publicBaseUrl;

    public UrlController(UrlService service,
            @Value("${shortener.public-base-url}") String publicBaseUrl) {
        this.service = service;
        URI base = URI.create(publicBaseUrl);
        if (!Destination.valid(publicBaseUrl) || base.getRawQuery() != null || base.getRawFragment() != null) {
            throw new IllegalArgumentException("Invalid public base URL configuration");
        }
        this.publicBaseUrl = publicBaseUrl.replaceAll("/+$", "");
    }

    static Instant parseExpiry(JsonNode value) {
        if (value == null || value.isNull()) return null;
        if (!value.isTextual()) throw new IllegalArgumentException("Invalid expiry type");
        try {
            OffsetDateTime parsed = OffsetDateTime.parse(value.textValue());
            if (!parsed.getOffset().equals(ZoneOffset.UTC)) throw new IllegalArgumentException("Expiry must be UTC");
            return parsed.toInstant();
        } catch (DateTimeParseException exception) {
            throw new IllegalArgumentException("Invalid expiry", exception);
        }
    }

    @PostMapping("/api/urls")
    public ResponseEntity<Created> create(@Valid @RequestBody CreateRequest body) {
        var saved = service.create(body.url().textValue(), parseExpiry(body.expiresAt()));
        String shortUrl = publicBaseUrl + "/r/" + saved.code();
        return ResponseEntity.created(URI.create(shortUrl)).body(new Created(
                saved.code(), shortUrl, saved.url(), saved.createdAt(), saved.expiresAt()));
    }

    @GetMapping("/r/{code}")
    public ResponseEntity<Void> redirect(@PathVariable("code") String code) {
        return ResponseEntity.status(302).location(URI.create(service.redirect(code))).build();
    }

    @GetMapping("/api/urls/{code}/analytics")
    public Analytics analytics(@PathVariable("code") String code) {
        var saved = service.analytics(code);
        return new Analytics(saved.code(), saved.url(), saved.createdAt(), saved.clickCount(),
                saved.lastAccessedAt(), saved.expiresAt());
    }
}

package com.urlshortner.urls;

import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice(assignableTypes = UrlController.class)
public class UrlErrors {
    public record ErrorBody(String error) {}

    @ExceptionHandler({MethodArgumentNotValidException.class, HttpMessageNotReadableException.class, IllegalArgumentException.class})
    public ResponseEntity<ErrorBody> invalid(Exception exception) {
        return ResponseEntity.badRequest().body(new ErrorBody("Invalid creation request"));
    }

    @ExceptionHandler(UrlService.UnknownCode.class)
    public ResponseEntity<ErrorBody> missing() {
        return ResponseEntity.status(404).body(new ErrorBody("Unknown code"));
    }

    @ExceptionHandler(UrlService.ExpiredCode.class)
    public ResponseEntity<ErrorBody> expired() {
        return ResponseEntity.status(410).body(new ErrorBody("Expired code"));
    }

    @ExceptionHandler(UrlService.AllocationExhausted.class)
    public ResponseEntity<ErrorBody> exhausted() {
        return ResponseEntity.status(503).body(new ErrorBody("Code allocation unavailable"));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorBody> internal(Exception exception) {
        return ResponseEntity.internalServerError().body(new ErrorBody("Internal server error"));
    }
}

package com.urlshortner.urls;

import java.sql.SQLException;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.time.temporal.ChronoUnit;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Optional;
import java.util.Set;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

@Repository
public class UrlRepository {
    public record StoredUrl(String code, String url, Instant createdAt, long clickCount,
            Instant lastAccessedAt, Instant expiresAt) {}

    private static final RowMapper<StoredUrl> MAPPER = (rs, row) -> {
        OffsetDateTime accessed = rs.getObject("last_accessed_at", OffsetDateTime.class);
        OffsetDateTime expiry = rs.getObject("expires_at", OffsetDateTime.class);
        return new StoredUrl(rs.getString("code"), rs.getString("url"),
                rs.getObject("created_at", OffsetDateTime.class).toInstant(),
                rs.getLong("click_count"), accessed == null ? null : accessed.toInstant(),
                expiry == null ? null : expiry.toInstant().plusNanos(rs.getInt("expires_at_submicro")));
    };

    private final JdbcTemplate jdbc;

    public UrlRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    static OffsetDateTime micros(Instant instant) {
        return instant.truncatedTo(ChronoUnit.MICROS).atOffset(ZoneOffset.UTC);
    }

    public StoredUrl insert(String code, String url, Instant expiresAt) {
        return jdbc.queryForObject("""
                INSERT INTO url_service.urls (code, url, expires_at, expires_at_submicro)
                VALUES (?, ?, ?, ?)
                RETURNING code, url, created_at, click_count, last_accessed_at,
                          expires_at, expires_at_submicro
                """, MAPPER, code, url, expiresAt == null ? null : micros(expiresAt),
                expiresAt == null ? null : expiresAt.getNano() % 1000);
    }

    public Optional<StoredUrl> find(String code) {
        return jdbc.query("""
                SELECT code, url, created_at, click_count, last_accessed_at,
                       expires_at, expires_at_submicro
                FROM url_service.urls WHERE code = ?
                """, MAPPER, code).stream().findFirst();
    }

    public Optional<String> recordRedirect(String code, Instant now) {
        OffsetDateTime evaluated = micros(now);
        return jdbc.query("""
                UPDATE url_service.urls
                SET click_count = click_count + 1, last_accessed_at = ?
                WHERE code = ? AND (expires_at IS NULL OR expires_at > ?
                    OR (expires_at = ? AND expires_at_submicro > ?))
                RETURNING url
                """, (rs, row) -> rs.getString("url"), evaluated, code,
                evaluated, evaluated, now.getNano() % 1000).stream().findFirst();
    }

    static boolean isCodeConflict(DataAccessException failure) {
        return isCodeConflict(failure, Collections.newSetFromMap(new IdentityHashMap<>()));
    }

    private static boolean isCodeConflict(Throwable failure, Set<Throwable> seen) {
        if (failure == null || !seen.add(failure)) return false;
        if (failure instanceof SQLException sql) {
            if ("23505".equals(sql.getSQLState()) && namedCodeConstraint(sql)) return true;
            if (isCodeConflict(sql.getNextException(), seen)) return true;
        }
        return isCodeConflict(failure.getCause(), seen);
    }

    private static boolean namedCodeConstraint(SQLException failure) {
        if (!failure.getClass().getName().equals("org.postgresql.util.PSQLException")) return false;
        try {
            Object detail = failure.getClass().getMethod("getServerErrorMessage").invoke(failure);
            if (detail == null) return false;
            return "pk_urls_code".equals(detail.getClass().getMethod("getConstraint").invoke(detail))
                    && "url_service".equals(detail.getClass().getMethod("getSchema").invoke(detail))
                    && "urls".equals(detail.getClass().getMethod("getTable").invoke(detail));
        } catch (ReflectiveOperationException | SecurityException exception) {
            return false;
        }
    }
}

package com.urlshortner.urls;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.dao.DataAccessException;
import org.springframework.stereotype.Service;

@Service
public class UrlService {
    public static final class UnknownCode extends RuntimeException {}
    public static final class ExpiredCode extends RuntimeException {}
    public static final class AllocationExhausted extends RuntimeException {}

    private final UrlRepository repository;
    private final CodeGenerator codes;
    private final Clock clock;
    private final Duration maximumExpiry;

    public UrlService(UrlRepository repository, CodeGenerator codes, Clock clock,
            @Value("${shortener.max-expiry-days:7}") long maximumDays) {
        if (maximumDays <= 0) throw new IllegalArgumentException("Invalid maximum expiry configuration");
        this.repository = repository;
        this.codes = codes;
        this.clock = clock;
        this.maximumExpiry = Duration.ofDays(Math.min(maximumDays, 7L));
    }

    // No surrounding transaction: a uniqueness failure must not abort later attempts.
    public UrlRepository.StoredUrl create(String url, Instant expiresAt) {
        if (!Destination.valid(url)) throw new IllegalArgumentException("Invalid destination");
        Instant now = clock.instant();
        if (expiresAt != null && (!expiresAt.isAfter(now)
                || expiresAt.isAfter(now.plus(maximumExpiry)))) {
            throw new IllegalArgumentException("Invalid expiry");
        }
        for (int attempt = 0; attempt < 5; attempt++) {
            try {
                return repository.insert(codes.next(), url, expiresAt);
            } catch (DataAccessException exception) {
                if (!UrlRepository.isCodeConflict(exception)) throw exception;
            }
        }
        throw new AllocationExhausted();
    }

    public String redirect(String code) {
        Instant now = clock.instant();
        var destination = repository.recordRedirect(code, now);
        if (destination.isPresent()) return destination.get();
        var stored = repository.find(code).orElseThrow(UnknownCode::new);
        if (stored.expiresAt() != null && !stored.expiresAt().isAfter(now)) throw new ExpiredCode();
        throw new IllegalStateException("Eligible redirect was not updated");
    }

    public UrlRepository.StoredUrl analytics(String code) {
        return repository.find(code).orElseThrow(UnknownCode::new);
    }
}

package com.urlshortner.urls;

import com.fasterxml.jackson.databind.JsonNode;
import jakarta.validation.Constraint;
import jakarta.validation.ConstraintValidator;
import jakarta.validation.ConstraintValidatorContext;
import jakarta.validation.Payload;
import java.lang.annotation.Retention;
import java.lang.annotation.Target;
import static java.lang.annotation.ElementType.*;
import static java.lang.annotation.RetentionPolicy.RUNTIME;

@Target({FIELD, PARAMETER, RECORD_COMPONENT, ANNOTATION_TYPE})
@Retention(RUNTIME)
@Constraint(validatedBy = ValidDestination.Validator.class)
public @interface ValidDestination {
    String message() default "url must be an HTTP or HTTPS destination without credentials or control characters";
    Class<?>[] groups() default {};
    Class<? extends Payload>[] payload() default {};

    class Validator implements ConstraintValidator<ValidDestination, JsonNode> {
        @Override
        public boolean isValid(JsonNode value, ConstraintValidatorContext context) {
            return value != null && value.isTextual() && Destination.valid(value.textValue());
        }
    }
}

